/**
 * @name Parameter data flowing into regex operations
 * @description Taint from library function parameters into regex subject arguments (ReDoS reachability)
 * @kind path-problem
 * @problem.severity warning
 * @id py/param-to-regex-redos
 * @tags security
 *        external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

predicate inTargetModule(DataFlow::Node n) {
  n.getLocation().getFile().getRelativePath().regexpMatch(".*(networks|_validators|types|datetime_parse|errors)\\.py")
}

predicate isRegexSink(DataFlow::Node n) {
  exists(Call c |
    c.getFunc().(Attribute).getAttr() in ["match", "search", "fullmatch", "sub", "subn", "findall", "split", "compile", "finditer"] and
    n = DataFlow::exprNode(c.getAnArg())
  )
}

module ReConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node n) {
    n instanceof DataFlow::ParameterNode and inTargetModule(n)
  }

  predicate isSink(DataFlow::Node n) { isRegexSink(n) }
}

module ReFlow = TaintTracking::Global<ReConfig>;

import ReFlow::PathGraph

from ReFlow::PathNode src, ReFlow::PathNode sink
where ReFlow::flowPath(src, sink)
select sink.getNode(), src, sink, "User-controlled data reaches regex engine $@ (possible ReDoS).", src.getNode(), "input"
